import "dotenv/config";
import { defineConfig } from "prisma/config";

/**
 * `prisma generate` veritabanına bağlanmaz; yalnızca istemci kodunu üretir.
 * Önizleme derlemelerinde DATABASE_URL yoktur (yalnızca Production'da tanımlı).
 * `env("DATABASE_URL")` bu durumda config yüklenirken fırlatır ve build düşer.
 *
 * Generate sırasında değişken yoksa yerel, kimlik bilgisi içermeyen bir
 * yer tutucu yazılır ki şemadaki `env("DATABASE_URL")` de suskun kalsın.
 * Yer tutucu üretim veritabanı değildir ve bağlantı açmaz.
 * Migrate / db komutları gerçek URL olmadan yine hata verir.
 */
const generating = process.argv.includes("generate");
if (generating && !process.env.DATABASE_URL) {
  process.env.DATABASE_URL = "postgresql://127.0.0.1:5432/placeholder";
}

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  engine: "classic",
  datasource: {
    url: process.env.DATABASE_URL ?? "",
  },
});
